import{_ as e,o as a,c as r,ag as d}from"./chunks/framework.4s5LDCII.js";const n=JSON.parse('{"title":"成人高脂血症食养指南（2023年版）","description":"国家卫健委《成人高脂血症食养指南（2023年版）》可执行整理：控油控胆固醇的行动清单，每条出处可一键跳回原文对应页。","frontmatter":{"title":"成人高脂血症食养指南（2023年版）","issuer":"国家卫生健康委办公厅","source_tier":"一级来源","version":"2023年版","published":"2023-01","source_url":"https://www.nhc.gov.cn/wjw/c100378/202301/7faed9993c9b45aea158c5335346f282.shtml","status":"现行","tags":["高血脂","食养","限油","饮食指导","行动清单"],"reviewed":false,"description":"国家卫健委《成人高脂血症食养指南（2023年版）》可执行整理：控油控胆固醇的行动清单，每条出处可一键跳回原文对应页。"},"headers":[],"relativePath":"guides/hyperlipidemia-2023.md","filePath":"guides/hyperlipidemia-2023.md"}'),i={name:"guides/hyperlipidemia-2023.md"};function h(p,t,g,l,s,o){return a(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="成人高脂血症食养指南-2023年版" tabindex="-1">成人高脂血症食养指南（2023年版） <a class="header-anchor" href="#成人高脂血症食养指南-2023年版" aria-label="Permalink to &quot;成人高脂血症食养指南（2023年版）&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">初稿待人工校验</p><p>本页由 AI 依据官方 PDF 原文整理，尚未逐条对照原文校验；校验通过前请以原文为准。</p></div><div class="danger custom-block"><p class="custom-block-title">使用须知</p><p>本页所有建议均<strong>整理自官方文件原文</strong>，每条&quot;出处&quot;均可点击直达原文对应页；标注【本站提示】的少数条目为中性工具提示，不代表医学建议。本站不构成诊疗建议，与医生的治疗方案冲突时，<strong>以医嘱为准</strong>。</p></div><blockquote><p><strong>原文出处</strong>：国家卫生健康委办公厅印发（<a href="https://www.nhc.gov.cn/wjw/c100378/202301/7faed9993c9b45aea158c5335346f282.shtml" target="_blank" rel="noreferrer">通知页</a>）· 一级来源。下文&quot;出处&quot;链接指向本站镜像的<a href="https://yshuai.github.io/SageRelay/guides-pdf/hyperlipidemia-2023.pdf" target="_blank" rel="noreferrer">官方原文 PDF</a>（政府公文，属公共领域）。</p></blockquote><h2 id="这份文件适合谁" tabindex="-1">这份文件适合谁 <a class="header-anchor" href="#这份文件适合谁" aria-label="Permalink to &quot;这份文件适合谁&quot;">​</a></h2><p>成人高脂血症（高胆固醇、高甘油三酯等血脂异常）人群，以及体检发现血脂偏高、心血管风险较高者及其家人；基层卫生工作者与营养指导人员亦可参考（<a href="https://yshuai.github.io/SageRelay/guides-pdf/hyperlipidemia-2023.pdf#page=3" target="_blank" rel="noreferrer">原文·前言</a>）。</p><h2 id="速览卡-一屏看完" tabindex="-1">速览卡（一屏看完） <a class="header-anchor" href="#速览卡-一屏看完" aria-label="Permalink to &quot;速览卡（一屏看完）&quot;">​</a></h2><p><strong>八条原则</strong>：吃动平衡、保持健康体重 → 调控脂肪、少油烹饪 → 食物多样、蛋白质和膳食纤维充足 → 少盐控糖、戒烟限酒 → 因人制宜、辨证施膳 → 因时制宜、分季调理 → 因地制宜、合理搭配 → 会看慧选、适量食用食药物质。（<a href="https://yshuai.github.io/SageRelay/guides-pdf/hyperlipidemia-2023.pdf#page=5" target="_blank" rel="noreferrer">原文·三</a>）</p><table tabindex="0"><thead><tr><th>关键数字（每日，除注明外）</th><th>数值</th><th>出处</th></tr></thead><tbody><tr><td>脂肪供能比</td><td><strong>20%～25%</strong>（按 1800～2000kcal 计，全天脂肪 40～55g）</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/hyperlipidemia-2023.pdf#page=7" target="_blank" rel="noreferrer">三(二)</a></td></tr><tr><td>烹调油</td><td><strong>≤25g</strong></td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/hyperlipidemia-2023.pdf#page=7" target="_blank" rel="noreferrer">三(二)</a></td></tr><tr><td>饱和脂肪</td><td>&lt;总能量 <strong>10%</strong>（高胆固醇血症者 &lt;7%）</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/hyperlipidemia-2023.pdf#page=7" target="_blank" rel="noreferrer">三(二)</a></td></tr><tr><td>膳食胆固醇</td><td><strong>&lt;300mg</strong>（高胆固醇血症者 &lt;200mg）</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/hyperlipidemia-2023.pdf#page=7" target="_blank" rel="noreferrer">三(二)</a></td></tr><tr><td>反式脂肪酸</td><td>&lt;总能量 <strong>1%</strong>（每天 ≤2g）</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/hyperlipidemia-2023.pdf#page=7" target="_blank" rel="noreferrer">三(二)</a></td></tr><tr><td>蔬菜</td><td><strong>500g</strong>，深色蔬菜占一半以上</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/hyperlipidemia-2023.pdf#page=8" target="_blank" rel="noreferrer">三(三)</a></td></tr><tr><td>水果</td><td><strong>200～350g</strong></td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/hyperlipidemia-2023.pdf#page=8" target="_blank" rel="noreferrer">三(三)</a></td></tr><tr><td>膳食纤维</td><td><strong>25～40g</strong>（其中水溶性 7～13g）</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/hyperlipidemia-2023.pdf#page=8" target="_blank" rel="noreferrer">三(三)</a></td></tr><tr><td>大豆蛋白</td><td>含 <strong>25g</strong> 大豆蛋白的食品</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/hyperlipidemia-2023.pdf#page=8" target="_blank" rel="noreferrer">三(三)</a></td></tr><tr><td>食盐</td><td><strong>≤5g</strong></td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/hyperlipidemia-2023.pdf#page=8" target="_blank" rel="noreferrer">三(四)</a></td></tr><tr><td>添加糖</td><td>&lt;总能量 <strong>10%</strong>（肥胖和高甘油三酯血症者更低）</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/hyperlipidemia-2023.pdf#page=8" target="_blank" rel="noreferrer">三(四)</a></td></tr><tr><td>运动</td><td><strong>每周 5～7 次、每次 30 分钟</strong>中等及以上强度，每天至少消耗 200kcal</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/hyperlipidemia-2023.pdf#page=5" target="_blank" rel="noreferrer">三(一)</a></td></tr></tbody></table><h2 id="行动清单" tabindex="-1">行动清单 <a class="header-anchor" href="#行动清单" aria-label="Permalink to &quot;行动清单&quot;">​</a></h2><h3 id="🛒-买" tabindex="-1">🛒 买 <a class="header-anchor" href="#🛒-买" aria-label="Permalink to &quot;🛒 买&quot;">​</a></h3><table tabindex="0"><thead><tr><th>怎么做</th><th>出处</th></tr></thead><tbody><tr><td>鱼虾类、去皮禽肉、瘦肉等低脂动物蛋白优先</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/hyperlipidemia-2023.pdf#page=8" target="_blank" rel="noreferrer">三(三)</a></td></tr><tr><td>奶类选<strong>脱脂或低脂</strong>牛奶</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/hyperlipidemia-2023.pdf#page=8" target="_blank" rel="noreferrer">三(三)</a></td></tr><tr><td>少买动物脑、动物内脏等高胆固醇食物</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/hyperlipidemia-2023.pdf#page=7" target="_blank" rel="noreferrer">三(二)</a></td></tr><tr><td>避免部分氢化植物油等含反式脂肪酸的食物</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/hyperlipidemia-2023.pdf#page=7" target="_blank" rel="noreferrer">三(二)</a></td></tr><tr><td>【本站提示】买包装食品先看营养成分表的脂肪、钠两项</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/hyperlipidemia-2023.pdf#page=12" target="_blank" rel="noreferrer">三(八)</a></td></tr></tbody></table><h3 id="🍳-做" tabindex="-1">🍳 做 <a class="header-anchor" href="#🍳-做" aria-label="Permalink to &quot;🍳 做&quot;">​</a></h3><table tabindex="0"><thead><tr><th>怎么做</th><th>出处</th></tr></thead><tbody><tr><td>少油烹饪：少油炸、油煎，多蒸、煮</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/hyperlipidemia-2023.pdf#page=7" target="_blank" rel="noreferrer">三(二)</a></td></tr><tr><td>主食控制精白米面，多全谷物、杂豆、蔬菜</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/hyperlipidemia-2023.pdf#page=8" target="_blank" rel="noreferrer">三(三)</a></td></tr><tr><td>【本站提示】用带刻度的油壶把&quot;每日烹调油 ≤25g&quot;落到每道菜</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/hyperlipidemia-2023.pdf#page=7" target="_blank" rel="noreferrer">三(二)</a></td></tr></tbody></table><h3 id="🍚-吃" tabindex="-1">🍚 吃 <a class="header-anchor" href="#🍚-吃" aria-label="Permalink to &quot;🍚 吃&quot;">​</a></h3><table tabindex="0"><thead><tr><th>怎么吃</th><th>出处</th></tr></thead><tbody><tr><td>食物每天 ≥12 种、每周 ≥25 种</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/hyperlipidemia-2023.pdf#page=8" target="_blank" rel="noreferrer">三(三)</a></td></tr><tr><td>每日膳食纤维 25～40g：全谷物、杂豆、蔬菜</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/hyperlipidemia-2023.pdf#page=8" target="_blank" rel="noreferrer">三(三)</a></td></tr><tr><td>每天摄入含 25g 大豆蛋白的豆制品</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/hyperlipidemia-2023.pdf#page=8" target="_blank" rel="noreferrer">三(三)</a></td></tr><tr><td>盐每日 ≤5g；少吃酱油、鸡精、味精、咸菜、咸肉、酱菜</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/hyperlipidemia-2023.pdf#page=8" target="_blank" rel="noreferrer">三(四)</a></td></tr><tr><td>甜食少吃，添加糖 &lt;总能量 10%</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/hyperlipidemia-2023.pdf#page=8" target="_blank" rel="noreferrer">三(四)</a></td></tr><tr><td>完全戒烟、避免二手烟；限制饮酒</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/hyperlipidemia-2023.pdf#page=8" target="_blank" rel="noreferrer">三(四)</a></td></tr><tr><td>按中医证型辨证施膳，总则&quot;实则泻之、虚则补之&quot;，食药物质见附录</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/hyperlipidemia-2023.pdf#page=9" target="_blank" rel="noreferrer">三(五)</a>、<a href="https://yshuai.github.io/SageRelay/guides-pdf/hyperlipidemia-2023.pdf#page=14" target="_blank" rel="noreferrer">附录1·二</a></td></tr><tr><td>分季调理：春季护阳保肝（芹菜、芦笋）；长夏清利湿热（薏苡仁、赤小豆）；秋季滋阴润肺（桑椹、百合）；冬季散寒补肾（羊肉、枸杞子）</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/hyperlipidemia-2023.pdf#page=10" target="_blank" rel="noreferrer">三(六)</a></td></tr><tr><td>因地制宜，按所在地区合理搭配</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/hyperlipidemia-2023.pdf#page=11" target="_blank" rel="noreferrer">三(七)</a></td></tr></tbody></table><h3 id="🏃-动" tabindex="-1">🏃 动 <a class="header-anchor" href="#🏃-动" aria-label="Permalink to &quot;🏃 动&quot;">​</a></h3><table tabindex="0"><thead><tr><th>怎么动</th><th>出处</th></tr></thead><tbody><tr><td>每周 5～7 次、每次 30 分钟中等及以上强度（快走、跑步、游泳、爬山、球类），每天至少消耗 200kcal</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/hyperlipidemia-2023.pdf#page=5" target="_blank" rel="noreferrer">三(一)</a></td></tr><tr><td>超重肥胖者：每日能量减少 300～500kcal，目标体重减少 <strong>10% 以上</strong></td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/hyperlipidemia-2023.pdf#page=5" target="_blank" rel="noreferrer">三(一)</a></td></tr><tr><td>稳定性动脉粥样硬化性心血管疾病患者：先做运动负荷试验评估安全性，循序渐进、量力而行</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/hyperlipidemia-2023.pdf#page=5" target="_blank" rel="noreferrer">三(一)</a></td></tr></tbody></table><h3 id="🩺-测与就医" tabindex="-1">🩺 测与就医 <a class="header-anchor" href="#🩺-测与就医" aria-label="Permalink to &quot;🩺 测与就医&quot;">​</a></h3><table tabindex="0"><thead><tr><th>怎么做</th><th>出处</th></tr></thead><tbody><tr><td>定期复查血脂，把血脂、血压、血糖控制在理想水平</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/hyperlipidemia-2023.pdf#page=8" target="_blank" rel="noreferrer">三(四)</a></td></tr><tr><td>规律作息、睡眠充足、保持情绪乐观</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/hyperlipidemia-2023.pdf#page=8" target="_blank" rel="noreferrer">三(四)</a></td></tr><tr><td>会看慧选：看懂营养标签，适量食用食药物质</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/hyperlipidemia-2023.pdf#page=12" target="_blank" rel="noreferrer">三(八)</a></td></tr></tbody></table><h2 id="常见误区-原文明确告诫" tabindex="-1">常见误区（原文明确告诫） <a class="header-anchor" href="#常见误区-原文明确告诫" aria-label="Permalink to &quot;常见误区（原文明确告诫）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>误区</th><th>原文怎么说</th><th>出处</th></tr></thead><tbody><tr><td>&quot;只有肥肉才有脂肪&quot;</td><td>全天脂肪包括烹调油、动物性食品及坚果等食物中的油脂</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/hyperlipidemia-2023.pdf#page=7" target="_blank" rel="noreferrer">三(二)</a></td></tr><tr><td>&quot;少量喝酒没关系&quot;</td><td>研究证明即使少量饮酒也可使高甘油三酯血症人群甘油三酯水平进一步升高</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/hyperlipidemia-2023.pdf#page=8" target="_blank" rel="noreferrer">三(四)</a></td></tr><tr><td>&quot;血脂高就该猛运动&quot;</td><td>稳定性动脉粥样硬化性心血管疾病患者应先进行运动负荷试验、充分评估安全性</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/hyperlipidemia-2023.pdf#page=5" target="_blank" rel="noreferrer">三(一)</a></td></tr><tr><td>&quot;精白米面不升血脂&quot;</td><td>碳水供能应占 50%～60%，适当控制精白米面、多吃膳食纤维</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/hyperlipidemia-2023.pdf#page=8" target="_blank" rel="noreferrer">三(三)</a></td></tr></tbody></table><h2 id="证型与食谱怎么用" tabindex="-1">证型与食谱怎么用 <a class="header-anchor" href="#证型与食谱怎么用" aria-label="Permalink to &quot;证型与食谱怎么用&quot;">​</a></h2><ul><li><strong><a href="https://yshuai.github.io/SageRelay/guides-pdf/hyperlipidemia-2023.pdf#page=13" target="_blank" rel="noreferrer">附录1《食物选择》</a></strong>：分食物类别的具体选择建议；**<a href="https://yshuai.github.io/SageRelay/guides-pdf/hyperlipidemia-2023.pdf#page=14" target="_blank" rel="noreferrer">附录1·二</a>**按痰浊内阻、痰瘀互结等证型给出食药物质推荐（在限定使用范围和剂量内使用，食用方法请咨询医师、营养指导人员）。</li><li><strong><a href="https://yshuai.github.io/SageRelay/guides-pdf/hyperlipidemia-2023.pdf#page=15" target="_blank" rel="noreferrer">附录2《常见食物交换表》</a></strong>：同类食物等量交换。</li><li><strong><a href="https://yshuai.github.io/SageRelay/guides-pdf/hyperlipidemia-2023.pdf#page=21" target="_blank" rel="noreferrer">附录3《不同证型食谱示例》</a><strong>与</strong><a href="https://yshuai.github.io/SageRelay/guides-pdf/hyperlipidemia-2023.pdf#page=34" target="_blank" rel="noreferrer">附录4《不同证型食养方举例》</a></strong>：按六个证型（痰浊内阻、痰瘀互结、气滞血瘀、气虚血瘀、肝肾阴虚、脾虚湿盛）各给食谱与食养方。</li></ul><h2 id="原文与溯源" tabindex="-1">原文与溯源 <a class="header-anchor" href="#原文与溯源" aria-label="Permalink to &quot;原文与溯源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>内容</th></tr></thead><tbody><tr><td>发布机构</td><td>国家卫生健康委办公厅</td></tr><tr><td>版本</td><td>2023 年版（现行）</td></tr><tr><td>印发时间</td><td>2023 年 1 月</td></tr><tr><td>原文直链</td><td><a href="https://www.nhc.gov.cn/wjw/c100378/202301/7faed9993c9b45aea158c5335346f282.shtml" target="_blank" rel="noreferrer">卫健委通知页</a></td></tr></tbody></table>',26)])])}const u=e(i,[["render",h]]);export{n as __pageData,u as default};
